algorithm RecursiveBoundaryReoptimization(problem, resource_limit):
    memo ← empty_map()                     // cache: cluster_signature → best_local_solution
    start_time ← now(); best_global ← null
    hierarchy ← MultiScalePartition(problem) // create coarse-to-fine partitions (graph/job clusters)
    while not Terminate(start_time, resource_limit):
        for level in hierarchy.coarse_to_fine():
            contracted ← ContractClusters(problem, level)                  // collapse clusters into supernodes
            for cluster in contracted.clusters:
                sig ← ClusterSignature(cluster, problem)                   // invariant summary for caching
                if sig in memo: local_sol ← memo[sig] else
                    local_sol ← SolveSubproblem(cluster, problem, budget=level.budget)
                    memo[sig] ← local_sol
                InsertLocalSolution(contracted, cluster, local_sol)
            candidate ← StitchContractedSolutions(contracted)              // merge supernode tours/schedules/routes
            candidate ← BoundaryOptimize(candidate, neighborhood=level.boundary_size)
                // re-optimize nodes/jobs on cluster boundaries via small exact DP/min-cost-flow
            if Evaluate(candidate, problem) < Evaluate(best_global, problem): best_global ← candidate
        hierarchy ← RefineOrCoarsen(hierarchy, feedback=best_global, budget=resource_limit-now())
        if StagnationDetected(best_global, history): InjectRandomizedRepartition(hierarchy)
    return DecodeSolution(best_global, problem)

